 [InitializeOnLoad]public static class CastleBuildingSideGardens
 {
  const string Request="Assets/Editor/CQC/CastleBuildingSideGardens.request.txt";static double next;
  static CastleBuildingSideGardens(){EditorApplication.update+=Pending;}
  static void Pending(){if(EditorApplication.timeSinceStartup<next)return;next=EditorApplication.timeSinceStartup+1;if(!File.Exists(Request)||EditorApplication.isCompiling||EditorApplication.isUpdating||EditorApplication.isPlayingOrWillChangePlaymode||SceneManager.GetActiveScene().name!="MyForest")return;Undo.IncrementCurrentGroup();int group=Undo.GetCurrentGroup();try{Apply();Undo.CollapseUndoOperations(group);AssetDatabase.DeleteAsset(Request);}catch(Exception e){Undo.RevertAllDownToGroup(group);Directory.CreateDirectory("Logs");File.WriteAllText("Logs/CastleBuildingSideGardens-error.txt",e.ToString());Debug.LogException(e);AssetDatabase.MoveAsset(Request,Request+"."+DateTime.Now.ToString("yyyyMMddHHmmss")+".failed");}}
  class Side{public Vector3 Center,Right,Forward;public float HalfWidth,HalfLength;public string Name;}
  [MenuItem("Tools/City/Fill Only Castle And Chapel Sides With Gardens")]
  public static void Apply()
  {
   var mountain=GameObject.Find("Castle Mountain");if(!mountain)throw new InvalidOperationException("Castle missing.");if(mountain.transform.Find("Castle And Chapel Side Gardens"))return;var roads=mountain.transform.Find("Connected Castle Stone Roads");var floor=mountain.transform.Find("Inner Castle Mountain/Flat Inner Castle Floor").GetComponent<MeshCollider>();if(!roads||!floor)throw new InvalidOperationException("Castle roads and floor required.");var sites=new List<Side>();var obstacles=new List<Bounds>();
   foreach(string name in new[]{"Central Upper Floor Building","Large Upper Castle Church"}){var t=mountain.transform.Find(name);if(!t||!t.gameObject.activeInHierarchy)continue;var b=BoundsOf(t.gameObject);var right=Vector3.ProjectOnPlane(t.right,Vector3.up).normalized;var forward=Vector3.ProjectOnPlane(t.forward,Vector3.up).normalized;sites.Add(new Side{Center=b.center,Right=right,Forward=forward,HalfWidth=Mathf.Abs(right.x)*b.extents.x+Mathf.Abs(right.z)*b.extents.z,HalfLength=Mathf.Abs(forward.x)*b.extents.x+Mathf.Abs(forward.z)*b.extents.z,Name=name});obstacles.Add(b);}
   if(sites.Count!=2)throw new InvalidOperationException("Both castle and chapel required.");foreach(string name in new[]{"Large Courtyard Rook Tower","Old Fountain In Front Of Chapel","Upper Blacksmith And Boxwood Borders/Upper Courtyard Blacksmith","Castle Scaffold Elevator"}){var t=mountain.transform.Find(name);if(t&&t.gameObject.activeInHierarchy)obstacles.Add(BoundsOf(t.gameObject));}
   var triangles=new List<Vector2[]>();foreach(var f in roads.GetComponentsInChildren<MeshFilter>()){var v=f.sharedMesh.vertices;var ids=f.sharedMesh.triangles;for(int i=0;i<ids.Length;i+=3)triangles.Add(new[]{Flat(f.transform.TransformPoint(v[ids[i]])),Flat(f.transform.TransformPoint(v[ids[i+1]])),Flat(f.transform.TransformPoint(v[ids[i+2]]))});}
   const string nature="Assets/InnerverseInteractive/Ultimate Nature – Starter/Environment/";var grass=AssetDatabase.LoadAssetAtPath<TerrainLayer>(nature+"Terrain/Layers/UNS_Grass.terrainlayer");var dirt=AssetDatabase.LoadAssetAtPath<TerrainLayer>(nature+"Terrain/Layers/UNS_Dirt.terrainlayer");var flower=AssetDatabase.LoadAssetAtPath<GameObject>(nature+"Vegetation/Flowers/Prefabs/UNS_Flower.prefab");if(!grass||!dirt||!flower)throw new InvalidOperationException("Garden assets missing.");
   var original=mountain.GetComponentsInChildren<Transform>(true);var matrices=original.Select(t=>t.localToWorldMatrix).ToArray();var scene=SceneManager.GetActiveScene();string stamp=DateTime.Now.ToString("yyyyMMdd-HHmmss"),backup="Assets/ForestExpansion/Backups/MyForest-before-building-side-gardens-"+stamp+".unity";if(!EditorSceneManager.SaveScene(scene,backup,true))throw new IOException("Backup failed.");string folder="Assets/CityExpansion/BuildingSideGardens-"+stamp;Directory.CreateDirectory(folder);AssetDatabase.Refresh();var gm=Material(grass,"Continuous Side Lawn",folder);var dm=Material(dirt,"Continuous Side Soil",folder);dm.SetColor("_BaseColor",new Color(.72f,.65f,.54f));
   var root=new GameObject("Castle And Chapel Side Gardens");root.transform.SetParent(mountain.transform,false);Undo.RegisterCreatedObjectUndo(root,"Fill castle and chapel side gardens");var gv=new List<Vector3>();var dv=new List<Vector3>();var area=floor.bounds;float y=area.max.y+.028f,step=.6f;int flowers=0,cells=0;int[] sides=new int[4];Physics.SyncTransforms();
   for(float x=area.min.x;x<area.max.x;x+=step)for(float z=area.min.z;z<area.max.z;z+=step)
   {
    Vector3 center=new Vector3(x+step*.5f,y,z+step*.5f);int selected=-1,sign=1;float nearest=float.PositiveInfinity;
    for(int i=0;i<sites.Count;i++){var s=sites[i];Vector3 delta=center-s.Center;float lateral=Vector3.Dot(delta,s.Right),along=Mathf.Abs(Vector3.Dot(delta,s.Forward));float distance=Mathf.Abs(lateral)-s.HalfWidth;if(distance<.35f||distance>16||along>s.HalfLength+.6f)continue;if(distance<nearest){nearest=distance;selected=i;sign=lateral>=0?1:-1;}}
    if(selected<0)continue;var corners=new[]{new Vector3(x,y,z),new Vector3(x+step,y,z),new Vector3(x+step,y,z+step),new Vector3(x,y,z+step)};if(corners.Any(p=>!floor.Raycast(new Ray(p+Vector3.up*10,Vector3.down),out RaycastHit hit,20)))continue;
    var patch=new Bounds(center,new Vector3(step,.1f,step));if(obstacles.Any(b=>Mathf.Abs(center.x-b.center.x)<patch.extents.x+b.extents.x+.25f&&Mathf.Abs(center.z-b.center.z)<patch.extents.z+b.extents.z+.25f))continue;
    var polygon=new[]{new Vector2(x-.4f,z-.4f),new Vector2(x+step+.4f,z-.4f),new Vector2(x+step+.4f,z+step+.4f),new Vector2(x-.4f,z+step+.4f)};bool onRoad=false;foreach(var t in triangles){if(t.Max(v=>v.x)<x-.4f||t.Min(v=>v.x)>x+step+.4f||t.Max(v=>v.y)<z-.4f||t.Min(v=>v.y)>z+step+.4f)continue;if(Intersects(polygon,t)){onRoad=true;break;}}if(onRoad)continue;
    bool soil=nearest<3f;AddQuad(root.transform,corners,soil?dv:gv);cells++;sides[selected*2+(sign>0?1:0)]++;
    int ix=Mathf.RoundToInt((x-area.min.x)/step),iz=Mathf.RoundToInt((z-area.min.z)/step);if(soil&&ix%3==0&&iz%3==0){var go=(GameObject)PrefabUtility.InstantiatePrefab(flower);go.transform.SetParent(root.transform,true);go.transform.rotation=Quaternion.Euler(0,(ix*43+iz*31)%360,0);var b=BoundsOf(go);go.transform.localScale*=.42f/Mathf.Max(.001f,b.size.y);b=BoundsOf(go);go.transform.position+=new Vector3(center.x-b.center.x,y+.01f-b.min.y,center.z-b.center.z);go.name="Side Garden Flowers "+(++flowers).ToString("000");foreach(var c in go.GetComponentsInChildren<Collider>())UnityEngine.Object.DestroyImmediate(c);PrefabUtility.RecordPrefabInstancePropertyModifications(go.transform);}
   }
   if(cells<50||sides[0]+sides[1]==0||sides[2]+sides[3]==0)throw new InvalidOperationException("Insufficient garden area beside both buildings; current scene retained.");if(gv.Count>0)Save(root.transform,gv,gm,grass.tileSize,"Continuous Grass Along Building Sides",folder+"/SideGrass.asset");if(dv.Count>0)Save(root.transform,dv,dm,dirt.tileSize,"Soil And Flowers Along Side Walls",folder+"/SideDirt.asset");
   var previous=mountain.transform.Find("Side By Side Castle Flower Gardens");if(previous){Undo.RecordObject(previous.gameObject,"Replace scattered garden patches");previous.gameObject.SetActive(false);}for(int i=0;i<original.Length;i++)if(original[i].localToWorldMatrix!=matrices[i])throw new InvalidOperationException("An existing model moved; gardens rolled back.");AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(scene);if(!EditorSceneManager.SaveScene(scene))throw new IOException("Save failed.");SceneView.RepaintAll();Directory.CreateDirectory("Logs");File.WriteAllText("Logs/CastleBuildingSideGardens-report.txt","Replaced scattered grass/dirt patches with continuous planted areas only beside castle and chapel side walls, extending toward the roads. Inner 3m band uses earthy original dirt with flowers; adjoining open side area uses original green grass. Roads keep 0.4m clearance; building frontage excluded by side-wall projection and all building bounds protected. Covered "+(cells*step*step).ToString("F1")+" square meters; added "+flowers+" flower clusters. Side cell counts castle left/right, chapel left/right: "+string.Join(",",sides)+". Existing bushes, trees, models, roads and global terrain remain in place. Previous small-patch garden hidden.\nBackup: "+backup);Debug.Log("Continuous gardens added only beside castle and chapel; small patches replaced. Scene saved.");
  }
  static Material Material(TerrainLayer layer,string name,string folder){var m=new Material(Shader.Find("Universal Render Pipeline/Lit")){name=name};m.SetTexture("_BaseMap",layer.diffuseTexture);m.SetColor("_BaseColor",Color.white);m.SetFloat("_Smoothness",.05f);if(layer.normalMapTexture){m.SetTexture("_BumpMap",layer.normalMapTexture);m.SetFloat("_BumpScale",.5f);m.EnableKeyword("_NORMALMAP");}m.enableInstancing=true;AssetDatabase.CreateAsset(m,folder+"/"+name.Replace(" ","")+".mat");return m;}
  static void AddQuad(Transform parent,Vector3[] corners,List<Vector3> vertices){foreach(var p in corners)vertices.Add(parent.InverseTransformPoint(p));}
  static void Save(Transform parent,List<Vector3> vertices,Material material,Vector2 tile,string name,string path){var ids=new List<int>();var uv=new List<Vector2>();for(int i=0;i<vertices.Count;i++){var w=parent.TransformPoint(vertices[i]);uv.Add(new Vector2(w.x/Mathf.Max(.1f,tile.x),w.z/Mathf.Max(.1f,tile.y)));}for(int i=0;i<vertices.Count;i+=4){Vector3 n=Vector3.Cross(vertices[i+1]-vertices[i],vertices[i+2]-vertices[i]);if(parent.TransformDirection(n).y>0)ids.AddRange(new[]{i,i+1,i+2,i,i+2,i+3});else ids.AddRange(new[]{i,i+2,i+1,i,i+3,i+2});}var mesh=new Mesh{name=name,indexFormat=UnityEngine.Rendering.IndexFormat.UInt32};mesh.SetVertices(vertices);mesh.SetUVs(0,uv);mesh.SetTriangles(ids,0);mesh.RecalculateNormals();mesh.RecalculateTangents();mesh.RecalculateBounds();AssetDatabase.CreateAsset(mesh,path);var go=new GameObject(name);go.transform.SetParent(parent,false);go.AddComponent<MeshFilter>().sharedMesh=mesh;go.AddComponent<MeshRenderer>().sharedMaterial=material;}
  static Vector2 Flat(Vector3 p){return new Vector2(p.x,p.z);}
  static bool Intersects(Vector2[] a,Vector2[] b){foreach(var polygon in new[]{a,b})for(int i=0;i<polygon.Length;i++){var edge=polygon[(i+1)%polygon.Length]-polygon[i];if(edge.sqrMagnitude<.00001f)continue;var axis=new Vector2(-edge.y,edge.x).normalized;float amin=float.PositiveInfinity,amax=float.NegativeInfinity,bmin=amin,bmax=amax;foreach(var p in a){float v=Vector2.Dot(axis,p);amin=Mathf.Min(amin,v);amax=Mathf.Max(amax,v);}foreach(var p in b){float v=Vector2.Dot(axis,p);bmin=Mathf.Min(bmin,v);bmax=Mathf.Max(bmax,v);}if(amax<bmin||bmax<amin)return false;}return true;}
  static Bounds BoundsOf(GameObject go){var r=go.GetComponentsInChildren<Renderer>();var b=r[0].bounds;foreach(var part in r)b.Encapsulate(part.bounds);return b;}
 }
